 "<div style=\"font-family:'Montserrat', sans-serif;font-size:44px;font-weight:800;color:#8e1b1b;line-height:1.1\">L</div><div>50</div>": "<div style=\"font-family:'Montserrat', sans-serif;font-size:44px;font-weight:800;color:#8e1b1b;line-height:1.1\">L</div><div>50</div>",
 "<div style=\"font-family:'Montserrat', sans-serif;font-size:44px;font-weight:800;color:#8e1b1b;line-height:1.1\">C</div><div>100</div>": "<div style=\"font-family:'Montserrat', sans-serif;font-size:44px;font-weight:800;color:#8e1b1b;line-height:1.1\">C</div><div>100</div>",
